UnevaluatedCode.code:
switch($action)
    {
      case 'count':
      {
        switch($type)
        {
          case 'new_comments':
            $field_id = 'c.id';
            break;
          case 'unvalidated_comments':
            $field_id = 'id';
            break;
          case 'new_elements':
            $field_id = 'image_id';
            break;
          case 'updated_categories':
            $field_id = 'category_id';
            break;
          case 'new_users':
            $field_id = 'user_id';
            break;
        }
        $query = 'SELECT COUNT(DISTINCT '.$field_id.') '.$query.';';
        list($count) = functions_mysqli::pwg_db_fetch_row(functions_mysqli::pwg_query($query));
        return $count;
        break;
      }

      case 'info':
      {
        switch($type)
        {
          case 'new_comments':
            $field_id = 'c.id';
            break;
          case 'unvalidated_comments':
            $field_id = 'id';
            break;
          case 'new_elements':
            $field_id = 'image_id';
            break;
          case 'updated_categories':
            $field_id = 'category_id';
            break;
          case 'new_users':
            $field_id = 'user_id';
            break;
        }
        $query = 'SELECT DISTINCT '.$field_id.' '.$query.';';
        $infos = functions_mysqli::query2array($query);
        return $infos;
        break;
      }

      default:
        return null; // stop and return nothing
    }
